function nbr($p,$s,$m){$h=0;foreach($r in ([IO.File]::ReadAllText((Convert-Path $p),[Text.UTF8Encoding]::new(0))-replace'[^\x1e]*$').Split([char]30)){$t=$r-replace'^\r?\n?';$f=$t.Split([char]31);if($h){if($t){,$f}}elseif($f[0]-ceq'nanobuf'-and$f[1]-ceq'1'-and$f[2]-ceq$s-and"$($f[3])".Split('.')[0]-ceq$m){$h=1}else{break}};if(!$h){throw "nanobuf: $p is not $s v$m"}}
